#include <stdio.h>

int main() {
    double distance;
    int dist_int;
    double price = 0;

    printf("请输入行驶里程(千米): ");
    scanf("%lf", &distance);

    // 处理不足1千米按1千米计算的情况
    // 如果是整数，直接取整；如果是小数，向上取整
    if (distance <= 0) {
        printf("里程必须大于0\n");
        return 0;
    }

    // 向上取整逻辑
    dist_int = (int)distance;
    if (distance > dist_int) {
        dist_int++;
    }

    if (dist_int < 3) {
        price = 10;
    } else if (dist_int < 8) {
        price = 10 + (dist_int - 3) * 1.6;
    } else {
        price = 10 + (8 - 3) * 1.6 + (dist_int - 8) * 2.2;
    }

    printf("车费为: %.2f 元\n", price);
    return 0;
}

#include <stdio.h>

int main() {
    int n;
    printf("请输入一个整数: ");
    scanf("%d", &n);

    int d3 = (n % 3 == 0);
    int d5 = (n % 5 == 0);
    int d7 = (n % 7 == 0);
    int count = d3 + d5 + d7;

    if (count == 3) {
        printf("能同时被 3、5、7 整除\n");
    } else if (count == 2) {
        printf("能同时被其中两个数整除: ");
        if (d3 && d5) printf("3, 5\n");
        else if (d3 && d7) printf("3, 7\n");
        else if (d5 && d7) printf("5, 7\n");
    } else if (count == 1) {
        printf("只能被其中一个数整除: ");
        if (d3) printf("3\n");
        else if (d5) printf("5\n");
        else printf("7\n");
    } else {
        printf("不能被 3、5、7 中任何一个数整除\n");
    }
    return 0;
}

