#include <stdio.h>

int main() {
    double b, x, h, sum = 0, s;
    int i;

    printf("请输入积分上限 b: ");
    scanf("%lf", &b);

    // 将区间 [0, b] 分成 100 份
    h = b / 100.0;

    for(i = 0; i < 100; i++) {
        // 计算每个小矩形的左端点 x 坐标
        x = i * h;
        // 计算小矩形面积：底 * 高 = h * f(x)
        s = h * (x * x + x);
        sum += s;
    }

    printf("数值积分结果为: %f\n", sum);
    return 0;
}

