#include <stdio.h>

int main() {
    double height = 100.0;
    double distance = 0.0;
    int i;

    for(i = 1; i <= 10; i++) {
        // 落地时经过的路程 = 之前的路程 + 下落的高度
        distance += height;

        // 反弹高度减半
        height /= 2.0;

        // 如果不是最后一次落地，还要加上反弹上去的路程（因为题目问第10次落地时，不包括第10次反弹）
        if(i < 10) {
            distance += height;
        }
    }

    printf("第10次落地时共经过: %f 米\n", distance);
    printf("第10次反弹高度: %f 米\n", height);

    return 0;
}

#include <stdio.h>

int main() {
    int x, y, z;
    // x: 鸡翁, y: 鸡母, z: 鸡雏
    // x + y + z = 100 (只)
    // 5x + 3y + z/3 = 100 (钱)

    printf("鸡翁\t鸡母\t鸡雏\n");
    printf("--------------------\n");

    for(x = 0; x <= 20; x++) { // 100元最多买20只公鸡
        for(y = 0; y <= 33; y++) { // 100元最多买33只母鸡
            z = 100 - x - y;
            // z必须是3的倍数，且总钱数等于100
            if(z % 3 == 0 && 5 * x + 3 * y + z / 3 == 100) {
                printf("%d\t%d\t%d\n", x, y, z);
            }
        }
    }
    return 0;
}

#include <stdio.h>

int main() {
    int n = 1000;
    int count = 0;
    int i;

    // 末尾的0是由因数 2 * 5 产生的。
    // 在阶乘中，2的因子数量远多于5的因子数量，所以只需要统计因子5的个数。
    // 比如 5, 10, 15... 贡献一个5
    // 25, 50, 75... 额外贡献一个5 (25 = 5*5)
    // 125... 额外贡献两个5

    for(i = 5; i <= n; i *= 5) {
        count += n / i;
    }

    printf("1000! 末尾有 %d 个 0\n", count);
    return 0;
}

