#include <stdio.h>

int main() {
    int i, j, k;
    int n = 4; // 上半部分的行数（不含最中间行）

    // 上半部分（包括中间行）
    for(i = 0; i <= n; i++) {
        // 输出空格
        for(j = 0; j < n - i; j++) printf(" ");
        // 输出星号
        for(k = 0; k < 2 * i + 1; k++) printf("*");
        printf("\n");
    }

    // 下半部分
    for(i = n - 1; i >= 0; i--) {
        // 输出空格
        for(j = 0; j < n - i; j++) printf(" ");
        // 输出星号
        for(k = 0; k < 2 * i + 1; k++) printf("*");
        printf("\n");
    }

    return 0;
}

