#include <stdio.h>

// 求最大公约数
int gcd(int a, int b) {
    int r;
    while (b != 0) {
        r = a % b;
        a = b;
        b = r;
    }
    return a;
}

// 求最小公倍数
int lcm(int a, int b) {
    if (a == 0 || b == 0) return 0;
    return (a * b) / gcd(a, b);
}

int main() {
    int num1, num2;
    printf("请输入两个整数：");
    scanf("%d%d", &num1, &num2);

    printf("最大公约数：%d\n", gcd(num1, num2));
    printf("最小公倍数：%d\n", lcm(num1, num2));
    return 0;
}
