// 递归函数
// 观察公式，当n=0时，最内层是 sqrt(x)，或者可以理解为第1层是sqrt(1+sqrt(x))
// 更通用的递归结构：f(x, n) = sqrt(n + f(x, n-1))
// 边界条件：当n=0时，返回 sqrt(x)
double calc_f(double x, int n) {
    if (n == 0)
        return sqrt(x);
    else
        return sqrt(n + calc_f(x, n - 1));
}

int main() {
    double x;
    int n;
    printf("请输入x和n：");
    scanf("%lf%d", &x, &n);

    printf("结果是：%f\n", calc_f(x, n));
    return 0;
}
