#include <stdio.h>
#include <string.h>

void f(char s[], int n) {
    int len = strlen(s);
    if (len == 0) return;
    n = n % len; // 处理n大于字符串长度的情况

    char temp[100]; // 临时存储前n个字符
    int i;

    // 复制前n个字符到临时数组
    for (i = 0; i < n; i++) {
        temp[i] = s[i];
    }

    // 将剩余字符前移
    for (i = 0; i < len - n; i++) {
        s[i] = s[i + n];
    }

    // 将临时数组的字符放到末尾
    for (i = 0; i < n; i++) {
        s[len - n + i] = temp[i];
    }
}

int main() {
    char str[100];
    int n;
    printf("请输入字符串: ");
    gets(str);
    printf("请输入左移位数: ");
    scanf("%d", &n);

    f(str, n);
    printf("左移后: %s\n", str);
    return 0;
}
```

