```c
void sort(int *a, int size) {
    int *p, *q, *min_ptr, temp;
    // p 控制外层循环，指向当前待排序位置
    for (p = a; p < a + size - 1; p++) {
        min_ptr = p;
        // q 控制内层循环，寻找最小值
        for (q = p + 1; q < a + size; q++) {
            if (*q < *min_ptr) {
                min_ptr = q;
            }
        }
        // 交换
        if (min_ptr != p) {
            temp = *p;
            *p = *min_ptr;
            *min_ptr = temp;
        }
    }
}
```

