    float salary;
    int age;
} Staff;

int main()
{
    FILE *fp;
    Staff s;
    int i;
    long size = sizeof(Staff);

    if ((fp = fopen("STAFF.dm", "rb")) == NULL) exit(1);

    // 移动到最后一条记录的开始位置
    // SEEK_END (2) 指向文件尾，偏移量应为 -size
    if (fseek(fp, -size, 2) != 0) 
    {
        printf("Seek error or empty file\n");
        fclose(fp);
        exit(1);
    }

    for (i = 0; i < 3; i++)
    {
        fread(&s, size, 1, fp);
        printf("%s %.2f %d\n", s.name, s.salary, s.age);

        // 读取一条后，指针在当前记录尾（即下一条记录头，或者文件尾）
        // 要读前一条，需要回退 2 * size (回到刚才读的头，再回退一条)
        // 但第一次循环后，我们需要读倒数第二条。fseek的基准如果是SEEK_SET比较容易计算，如果是SEEK_CUR则需要小心。
        // 更稳妥的方法：
        if (fseek(fp, -2 * size, 1) != 0) break; // 1 表示 SEEK_CUR
    }

    fclose(fp);
    return 0;
}

